INSERT INTO modalidades (id, nome, slug, icone, descricao, ativo, categoria)
VALUES
(1, 'Andebol', 'andebol', '/icones-modalidades/andebol.png', 'O Ginásio Clube de Odivelas é uma referência no Andebol no Distrito de Lisboa, modalidade com tradição nesta coletividade há várias décadas. Atualmente, a equipa sénior continua a elevar o nome do clube, conquistando recentemente a Taça de Lisboa, um marco histórico que confirma a dedicação e qualidade dos atletas que vestem a camisola do GCO.', TRUE, 'Coletivo'),
(2, 'Ginástica', 'ginastica', '/icones-modalidades/ginastica.png', 'O Ginásio Clube de Odivelas é também um nome reconhecido na Ginástica de Trampolins, modalidade que tem vindo a crescer no clube e que forma jovens atletas com talento e disciplina. Ao longo dos anos, vários ginastas do GCO participaram em provas regionais e nacionais, consolidando a presença do clube nesta vertente da ginástica.', TRUE, 'Individual'),
(3, 'Patinagem Artística', 'patinagem-artistica', '/icones-modalidades/patinagem.png', 'O Ginásio Clube de Odivelas é uma referência na Patinagem Artística no Distrito de Lisboa, modalidade praticada nesta coletividade há mais de 40 anos.', TRUE, 'Individual'),
(4, 'Xadrez', 'xadrez', '/icones-modalidades/xadrez.png', 'Quer aprender a jogar Xadrez? Já sabe jogar mas não tem com quem praticar em casa? Apareça no GCO. Somos o único clube desportivo, federado, no Concelho de Odivelas que pratica esta modalidade há mais de trinta anos! Neste período alcançámos mais de 60 títulos nacionais e distritais (coletivos e individuais) e um da União Europeia. Junte-se a nós e traga familiares e amigos.', TRUE, 'Intelectual'),
(5, 'Hóquei em Patins', 'hoquei-em-patins', '/icones-modalidades/hoquei.png', 'Vem aprender a jogar Hóquei em Patins no GCO!', FALSE, 'Coletivo');
